+/**
+ * Variance per item between two days (inclusive): theoretical use from the
+ * sales sold then, actual use from every consume movement then, and
+ * actual - theoretical (3 decimals). Items with neither are left out.
+ */
+export function varianceReport(store, from, to) {
+  const inRange = (instant) => {
+    const day = dayOf(instant);
+    return day >= from && day <= to;
+  };
+  // Summed in thousandths so the totals stay exact.
+  const theoretical = new Map();
+  const actual = new Map();
+  const add = (map, itemId, qty) => map.set(itemId, (map.get(itemId) ?? 0) + Math.round(qty * 1000));
+  for (const sale of store.data.sales ?? [])
+    if (inRange(sale.soldAt)) for (const u of sale.uses) add(theoretical, u.itemId, u.qty);
+  const batchItem = new Map(store.data.batches.map((b) => [b.id, b.itemId]));
+  for (const m of store.data.movements)
+    if (m.type === "consume" && batchItem.has(m.batchId) && inRange(m.at)) add(actual, batchItem.get(m.batchId), m.qty);
+  return listItems(store)
+    .map((item) => {
+      const t = theoretical.get(item.id) ?? 0;
+      const a = actual.get(item.id) ?? 0;
+      return { itemId: item.id, name: item.name, unit: item.unit, theoretical: t / 1000, actual: a / 1000, difference: (a - t) / 1000 };
+    })
+    .filter((l) => l.theoretical > 0 || l.actual > 0);
+}
