+// Sales from the till. Each sale line is one dish on one ticket; it uses one
+// portion of the dish's recipe per `qty` and keeps what it used, so reports
+// can compare theoretical use with the ledger. A ticket is imported once.
+import { AppError } from "../errors.js";
+import { consume } from "./batches.js";
+import { getDish } from "./menu.js";
+import { getRecipe, scaled } from "./recipes.js";
+
+/** True when a ticket has already been imported. */
+export function hasTicket(store, ticket) {
+  return (store.data.sales ?? []).some((s) => s.ticket === ticket);
+}
+
+/**
+ * Records sale lines ({ row, ticket, soldAt, dishId, qty }) and consumes their
+ * ingredients at `soldAt`. Lines of tickets imported earlier are skipped. All
+ * or nothing: when an item runs out, the store is left as it was and
+ * sale_not_enough_stock names the row. Returns { tickets, dishes } imported.
+ */
+export function recordSales(store, lines) {
+  const fresh = lines.filter((l) => !hasTicket(store, l.ticket));
+  const { data } = store;
+  data.sales ??= [];
+  const before = structuredClone({ batches: data.batches, movements: data.movements, sales: data.sales, seq: data.seq });
+  try {
+    for (const line of fresh) {
+      const recipe = getRecipe(store, getDish(store, line.dishId).recipeId);
+      const uses = scaled(recipe, line.qty).filter((u) => u.qty > 0);
+      for (const u of uses) {
+        try {
+          consume(store, u.itemId, u.qty, { at: line.soldAt, ref: `sale:${line.ticket}` });
+        } catch (e) {
+          if (e instanceof AppError && e.code === "not_enough_stock")
+            throw new AppError("sale_not_enough_stock", { row: line.row, ...e.params });
+          throw e;
+        }
+      }
+      data.sales.push({ id: store.nextId("sale"), ticket: line.ticket, soldAt: line.soldAt, dishId: line.dishId, qty: line.qty, uses });
+    }
+  } catch (e) {
+    Object.assign(data, before);
+    throw e;
+  }
+  return { tickets: new Set(fresh.map((l) => l.ticket)).size, dishes: fresh.reduce((s, l) => s + l.qty, 0) };
+}
